            % Vẽ đường cao từ A xuống H
            \draw  (A) -- (H);

            % Vẽ góc vuông tại H
            \draw (H) rectangle ++(0.3, 0.3);   

            %Vẽ góc vuông tại A
            \pic[draw,angle radius=10]{right angle=B--A--C};
        \end{tikzpicture}
}
